        title='Cold Spring Harbor Laboratory Archives Digital Repository | View | Walter Gilbert Collection',
        description='The Walter Gilbert Collection at CSHL Library and Archives is composed of material accrued by Gilbert as a student (Sidwell Friends School, Harvard University, Cambridge University), professor (Harvard University), and as a pioneering entrepreneur in the field of biotechnology (Biogen). The collection includes course notebooks, lecture notes and teaching files, scientific papers, correspondence, photographs, memorabilia, clippings, and material related to receiving the Nobel Prize. \r\n\r\n The material has been divided into eight series:\r\nCoursework, 1948-1957\r\nTeaching and Lecture Files, 1959-2004\r\nBiogen, 1978-1981\r\nScientific Papers, 1949-2005\r\nClippings, 1948-2005\r\nCorrespondence, 1954-2005\r\nScientific Fraud, 1989, 1993\r\nMemorabilia and Ephemera, 1946-2011\r\nSee below for detailed descriptions and inventories of each individual series.\r\n<extptr href="http://library.cshl.edu/images/archives/Gilbert_0272_001_Harvard_News_Service.jpg" actuate="online" show="embed"><extptr>',
